"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[36777],{24712:(e,n,i)=>{i.d(n,{D:()=>o});let o={FREE_LIMIT:20,WARNING_THRESHOLD:15}},36777:(e,n,i)=>{i.d(n,{BX:()=>c,Br:()=>h,Ci:()=>l,IR:()=>p,oN:()=>d,pW:()=>g,t0:()=>m,xd:()=>u});var o=i(93887),a=i(24712),s=i(77678);let t=(0,o.Rg)("vn");if(!t)throw Error("faqs: MARKETS registry is missing the vn market");let r=e=>e.toLocaleString("vi-VN");(0,s.xv)("/"),r(t.tiers.new.amountMinor),r(t.tiers.returning.amountMinor),a.D.FREE_LIMIT,(0,s.xv)("/thiep-cuoi-long-phung"),"C\xf3. Chung Đ\xf4i đang mở rộng sang nhiều dịp kh\xe1c với c\xf9ng cơ chế thiệp ri\xeang cho từng kh\xe1ch, c\xf3 RSVP v\xe0 gallery ảnh:\n\n- **Sinh nhật:** [Thiệp mời sinh nhật online](".concat((0,s.xv)("/thiep-moi-sinh-nhat-online"),") cho b\xe9, cho người lớn, sinh nhật bất ngờ.\n- **Th\xf4i n\xf4i & đầy th\xe1ng:** [Thiệp mời th\xf4i n\xf4i & đầy th\xe1ng online](").concat((0,s.xv)("/thiep-moi-thoi-noi-day-thang"),") cho b\xe9 trai, b\xe9 g\xe1i, song sinh.\n\nXem đầy đủ c\xe1c dịp tại [trang thiệp mời online](").concat((0,s.xv)("/thiep-moi-online"),"). Tất cả đều miễn ph\xed d\xf9ng thử như thiệp cưới."),(0,s.xv)("/tao-thiep-cuoi-online"),(0,s.xv)("/blog/khi-nao-nen-gui-thiep-cuoi"),(0,s.xv)("/blog/cach-viet-loi-moi-cuoi"),(0,s.xv)("/tao-thiep-cuoi-online"),(0,s.xv)("/doi-ngay-am-duong"),(0,s.xv)("/tao-thiep-cuoi-online"),(0,s.xv)("/tao-thiep-cuoi-online"),(0,s.xv)("/tao-thiep-cuoi-online");let u=[{question:"Tại sao thiệp chưa được k\xedch hoạt sau khi chuyển khoản?",answer:"C\xf3 3 nguy\xean nh\xe2n phổ biến:\n\n- **Sai nội dung chuyển khoản:** Nội dung chuyển khoản cần chứa đ\xfang m\xe3 TC (v\xed dụ: TC123456). Nếu bạn nhập sai hoặc thiếu m\xe3, hệ thống kh\xf4ng thể tự động nhận diện.\n- **Ng\xe2n h\xe0ng chưa xử l\xfd xong:** Một số giao dịch li\xean ng\xe2n h\xe0ng mất 1–5 ph\xfat, đặc biệt ngo\xe0i giờ l\xe0m việc.\n- **Chuyển khoản thủ c\xf4ng:** Nếu bạn kh\xf4ng qu\xe9t m\xe3 QR m\xe0 nhập tay, nội dung chuyển khoản c\xf3 thể bị thiếu m\xe3 TC."},{question:"M\xe3 TC l\xe0 g\xec v\xe0 t\xecm ở đ\xe2u?",answer:"M\xe3 TC l\xe0 m\xe3 giao dịch duy nhất được tạo khi bạn nhấn thanh to\xe1n (v\xed dụ: TC350150). M\xe3 n\xe0y nằm trong nội dung chuyển khoản tr\xean m\xe3 QR.\n\nKhi bạn qu\xe9t m\xe3 QR bằng app ng\xe2n h\xe0ng, m\xe3 TC sẽ được điền tự động v\xe0o nội dung chuyển khoản. Nếu bạn chuyển khoản thủ c\xf4ng, h\xe3y nhớ nhập đ\xfang m\xe3 TC."},{question:"Gửi ảnh x\xe1c nhận chuyển khoản như thế n\xe0o?",answer:"V\xe0o trang **Hỗ trợ thanh to\xe1n**, t\xecm giao dịch đang chờ v\xe0 nhấn **Gửi ảnh x\xe1c nhận chuyển khoản**. Chụp ảnh m\xe0n h\xecnh giao dịch th\xe0nh c\xf4ng từ app ng\xe2n h\xe0ng (hiện r\xf5 số tiền v\xe0 nội dung chuyển khoản).\n\nHệ thống sẽ tự động đọc th\xf4ng tin từ ảnh v\xe0 k\xedch hoạt thiệp. Nếu ảnh r\xf5 r\xe0ng, thiệp được k\xedch hoạt trong v\xe0i gi\xe2y."},{question:"T\xf4i đ\xe3 gửi ảnh nhưng thiệp vẫn chưa được k\xedch hoạt?",answer:"Nếu hệ thống kh\xf4ng thể tự động x\xe1c nhận, đội ngũ hỗ trợ sẽ kiểm tra v\xe0 k\xedch hoạt thủ c\xf4ng trong thời gian sớm nhất.\n\nBạn cũng c\xf3 thể nhắn tin qua **Messenger** để được hỗ trợ trực tiếp."},{question:"Chuyển khoản nhầm số tiền th\xec sao?",answer:"Nếu bạn chuyển **nhiều hơn** số tiền cần thanh to\xe1n, thiệp vẫn được k\xedch hoạt b\xecnh thường. Hệ thống chấp nhận số tiền bằng hoặc lớn hơn gi\xe1 thiệp.\n\nNếu bạn chuyển **\xedt hơn**, thiệp sẽ kh\xf4ng được k\xedch hoạt tự động. H\xe3y li\xean hệ đội ngũ hỗ trợ qua Messenger để được gi\xfap đỡ."}],c=[{question:"What is an online wedding invitation?",answer:"An online wedding invitation is a beautifully designed digital page that replaces traditional paper invitations. With [ChungDoi.com](/en), you can:\n\n- Create stunning wedding invitations with features like guest wishes, gift QR codes, and smart guest management.\n- Easily invite friends and family anywhere in the world.\n- Keep your love story, photos, and memories forever in a digital keepsake."},{question:"How do I create an online wedding invitation?",answer:"You can create your own wedding invitation in just 3 simple steps:\n\n1. **Choose a template:** Browse our library and pick a design you love.\n2. **Add your details:** Fill in your names, date, venue, and upload your photos.\n3. **Share:** Publish your invitation and share the unique link with your guests."},{question:"How much does it cost?",answer:"Creating and customizing your invitation is completely **free**! You can design it however you like at no cost.\n\nAfter publishing, you get a **free 3-day trial** with full features. After that, a one-time payment keeps your invitation live forever. The price is shown clearly before you confirm."},{question:"How do guests receive the invitation?",answer:"You get a unique link to share with your guests. You can:\n\n1. **Send the link directly:** Share via WhatsApp, Messenger, email, or any messaging app.\n2. **Use a QR code:** Print the QR code on paper invitations so guests can scan and view your digital invitation instantly."},{question:"Do I need any design skills?",answer:"Not at all! All templates are professionally designed. You just choose a template and fill in your information — no layout adjustments, font selection, or color matching needed."},{question:"What information should I prepare?",answer:"To create your invitation quickly, have these ready:\n\n- **Couple info:** Full names of the bride and groom\n- **Family info:** Parents' names\n- **Event details:** Date, time, and venue for ceremony and reception\n- **Photos:** 5-10 of your favorite wedding photos\n- **Bank details:** Account number if you want to receive gifts via QR code"},{question:"Can I edit after publishing?",answer:"Yes! You can edit everything on your invitation anytime, even after publishing. All changes update instantly on the link you already shared — no need to resend."},{question:"How many guests can I invite?",answer:"There is no limit on the number of guests. Just share your invitation link and spread the joy to everyone!"}],d=[{question:"Qu'est-ce qu'un faire-part de mariage en ligne ?",answer:"Un faire-part de mariage en ligne est une page num\xe9rique au design soign\xe9 qui remplace les faire-part papier traditionnels. Avec [ChungDoi.com](/fr), vous pouvez :\n\n- Cr\xe9er de superbes faire-part de mariage avec des fonctionnalit\xe9s comme les voeux des invit\xe9s, la cagnotte QR et une gestion intelligente des invit\xe9s.\n- Inviter facilement vos proches partout dans le monde.\n- Conserver pour toujours votre histoire d'amour, vos photos et vos souvenirs dans un souvenir num\xe9rique."},{question:"Comment cr\xe9er un faire-part de mariage en ligne ?",answer:"Vous pouvez cr\xe9er votre faire-part de mariage en 3 \xe9tapes simples :\n\n1. **Choisissez un mod\xe8le :** Parcourez notre biblioth\xe8que et choisissez le design qui vous pla\xeet.\n2. **Ajoutez vos informations :** Renseignez vos pr\xe9noms, la date, le lieu et importez vos photos.\n3. **Partagez :** Publiez votre faire-part et partagez le lien unique avec vos invit\xe9s."},{question:"Combien \xe7a co\xfbte ?",answer:"Cr\xe9er et personnaliser votre faire-part est enti\xe8rement **gratuit** ! Vous pouvez le concevoir comme vous le souhaitez, sans aucun frais.\n\nApr\xe8s publication, vous b\xe9n\xe9ficiez d'un **essai gratuit de 3 jours** avec toutes les fonctionnalit\xe9s. Ensuite, un paiement unique garde votre faire-part en ligne pour toujours. Le prix est affich\xe9 clairement avant toute confirmation."},{question:"Comment les invit\xe9s re\xe7oivent-ils le faire-part ?",answer:"Vous obtenez un lien unique \xe0 partager avec vos invit\xe9s. Vous pouvez :\n\n1. **Envoyer le lien directement :** Via WhatsApp, Messenger, e-mail ou toute application de messagerie.\n2. **Utiliser un QR code :** Imprimez le QR code sur des faire-part papier pour que vos invit\xe9s le scannent et d\xe9couvrent instantan\xe9ment votre faire-part num\xe9rique."},{question:"Faut-il des comp\xe9tences en design ?",answer:"Pas du tout ! Tous les mod\xe8les sont con\xe7us par des professionnels. Il vous suffit de choisir un mod\xe8le et de renseigner vos informations, sans aucun r\xe9glage de mise en page, choix de police ni accord de couleurs."},{question:"Quelles informations dois-je pr\xe9parer ?",answer:"Pour cr\xe9er votre faire-part rapidement, pr\xe9parez ces \xe9l\xe9ments :\n\n- **Informations sur les mari\xe9s :** Noms complets de la mari\xe9e et du mari\xe9\n- **Informations sur la famille :** Noms des parents\n- **D\xe9tails de l'\xe9v\xe9nement :** Date, heure et lieu de la c\xe9r\xe9monie et de la r\xe9ception\n- **Photos :** 5 \xe0 10 de vos plus belles photos de mariage\n- **Coordonn\xe9es bancaires :** Num\xe9ro de compte si vous souhaitez recevoir des cadeaux via QR code"},{question:"Puis-je modifier apr\xe8s publication ?",answer:"Oui ! Vous pouvez modifier tout votre faire-part \xe0 tout moment, m\xeame apr\xe8s publication. Toutes les modifications se mettent \xe0 jour instantan\xe9ment sur le lien d\xe9j\xe0 partag\xe9, sans avoir \xe0 le renvoyer."},{question:"Combien d'invit\xe9s puis-je inviter ?",answer:"Le nombre d'invit\xe9s est illimit\xe9. Partagez simplement le lien de votre faire-part et faites rayonner la joie aupr\xe8s de tous !"}],l=[{question:"O que \xe9 um convite de casamento online?",answer:"Um convite de casamento online \xe9 uma p\xe1gina digital com design caprichado que substitui os convites de papel tradicionais. Com o [ChungDoi.com](/pt), voc\xea pode:\n\n- Criar convites de casamento incr\xedveis com recursos como mensagens dos convidados, presente via QR Code e gest\xe3o inteligente da lista de convidados.\n- Convidar facilmente seus entes queridos em qualquer lugar do mundo.\n- Guardar para sempre a sua hist\xf3ria de amor, suas fotos e suas mem\xf3rias em uma lembran\xe7a digital."},{question:"Como criar um convite de casamento online?",answer:"Voc\xea pode criar o seu convite de casamento em 3 passos simples:\n\n1. **Escolha um modelo:** Navegue pela nossa biblioteca e escolha o design que mais combina com voc\xea.\n2. **Adicione suas informa\xe7\xf5es:** Preencha os nomes do casal, a data, o local e envie suas fotos.\n3. **Compartilhe:** Publique o seu convite e compartilhe o link exclusivo com os convidados."},{question:"Quanto custa?",answer:"Criar e personalizar o seu convite \xe9 totalmente **gratuito**! Voc\xea pode montar do jeito que quiser, sem nenhum custo.\n\nAp\xf3s a publica\xe7\xe3o, voc\xea ganha um **per\xedodo de teste gratuito de 3 dias** com todos os recursos. Depois, um pagamento \xfanico mant\xe9m o seu convite no ar para sempre. O pre\xe7o aparece com clareza antes de qualquer confirma\xe7\xe3o."},{question:"Como os convidados recebem o convite?",answer:"Voc\xea recebe um link exclusivo para compartilhar com os convidados. Voc\xea pode:\n\n1. **Enviar o link diretamente:** Pelo WhatsApp, Messenger, e-mail ou qualquer aplicativo de mensagens.\n2. **Usar um QR Code:** Imprima o QR Code em convites de papel para que os convidados escaneiem e abram seu convite digital na hora."},{question:"Preciso ter habilidades de design?",answer:"De jeito nenhum! Todos os modelos s\xe3o criados por profissionais. Basta escolher um modelo e preencher suas informa\xe7\xf5es, sem precisar ajustar layout, escolher fontes ou combinar cores."},{question:"Quais informa\xe7\xf5es devo preparar?",answer:"Para criar o seu convite rapidinho, deixe estes itens \xe0 m\xe3o:\n\n- **Informa\xe7\xf5es do casal:** Nomes completos da noiva e do noivo\n- **Informa\xe7\xf5es da fam\xedlia:** Nomes dos pais\n- **Detalhes do evento:** Data, hor\xe1rio e local da cerim\xf4nia e da recep\xe7\xe3o\n- **Fotos:** 5 a 10 das suas fotos de casamento favoritas\n- **Dados banc\xe1rios:** N\xfamero da conta, caso queira receber presentes via QR Code"},{question:"Posso editar depois de publicar?",answer:"Sim! Voc\xea pode editar todo o seu convite a qualquer momento, mesmo depois de publicado. Todas as altera\xe7\xf5es s\xe3o atualizadas na hora no link que j\xe1 foi compartilhado, sem precisar enviar de novo."},{question:"Quantos convidados posso convidar?",answer:"O n\xfamero de convidados \xe9 ilimitado. \xc9 s\xf3 compartilhar o link do seu convite e espalhar a alegria para todo mundo!"}],h=[{question:"ما هي دعوة الزفاف الإلكترونية؟",answer:"دعوة الزفاف الإلكترونية صفحة رقمية بتصميم أنيق تحلّ محل الدعوات الورقية التقليدية. مع [ChungDoi.com](/ar) يمكنك:\n\n- إنشاء دعوات زفاف رائعة بمزايا مثل تهاني الضيوف، ورمز QR للهدايا، وإدارة ذكية لقائمة المدعوين.\n- دعوة الأهل والأصدقاء في أي مكان في العالم بسهولة.\n- الاحتفاظ بقصة حبكما وصوركما وذكرياتكما إلى الأبد في تذكار رقمي."},{question:"كيف أنشئ دعوة زفاف إلكترونية؟",answer:"يمكنك إنشاء دعوتك في 3 خطوات بسيطة فقط:\n\n1. **اختر قالبًا:** تصفّح مكتبتنا واختر تصميمًا يعجبك.\n2. **أضف تفاصيلك:** اكتب أسماءكما وتاريخ الزفاف ومكانه، وارفع صوركما.\n3. **شاركها:** انشر دعوتك وشارك الرابط الخاص بها مع ضيوفك."},{question:"كم تبلغ التكلفة؟",answer:"إنشاء دعوتك وتخصيصها **مجاني تمامًا**! صمّمها كما تحب دون أي تكلفة.\n\nبعد النشر تحصل على **تجربة مجانية لمدة 3 أيام** بكامل المزايا. بعدها، دفعة واحدة تبقي دعوتك فعّالة إلى الأبد. ويظهر السعر بوضوح قبل التأكيد."},{question:"كيف يستلم الضيوف الدعوة؟",answer:"تحصل على رابط فريد لمشاركته مع ضيوفك. يمكنك:\n\n1. **إرسال الرابط مباشرة:** عبر واتساب أو ماسنجر أو البريد الإلكتروني أو أي تطبيق مراسلة.\n2. **استخدام رمز QR:** اطبع رمز QR على الدعوات الورقية ليمسحه الضيوف ويفتحوا دعوتك الرقمية فورًا."},{question:"هل أحتاج إلى مهارات في التصميم؟",answer:"إطلاقًا! جميع القوالب مصمّمة باحترافية. ما عليك سوى اختيار قالب وتعبئة معلوماتك، دون الحاجة إلى ضبط التنسيق أو اختيار الخطوط أو تنسيق الألوان."},{question:"ما المعلومات التي ينبغي أن أجهّزها؟",answer:"لإنشاء دعوتك بسرعة، جهّز ما يلي:\n\n- **معلومات العروسين:** الأسماء الكاملة للعريس والعروس\n- **معلومات العائلة:** أسماء الوالدين\n- **تفاصيل المناسبة:** تاريخ ووقت ومكان مراسم العقد والحفل\n- **الصور:** من 5 إلى 10 من أجمل صوركما\n- **بيانات الحساب البنكي:** رقم الحساب إن أردت استقبال الهدايا عبر رمز QR"},{question:"هل يمكنني التعديل بعد النشر؟",answer:"نعم! يمكنك تعديل كل شيء في دعوتك في أي وقت، حتى بعد النشر. وتظهر كل التعديلات فورًا على الرابط الذي شاركته من قبل، دون الحاجة إلى إعادة إرساله."},{question:"كم عدد الضيوف الذين يمكنني دعوتهم؟",answer:"لا حدّ لعدد الضيوف. ما عليك سوى مشاركة رابط دعوتك ونشر الفرحة بين الجميع!"}],m=[{question:"什麼是電子喜帖？",answer:"電子喜帖是一個精美設計的數位頁面，可以取代傳統紙本喜帖。透過 [ChungDoi.com](/tw)，您可以：\n\n- 製作精美的婚禮邀請卡，包含賓客祝福留言、QR 紅包收禮、智慧賓客管理等功能。\n- 輕鬆邀請世界各地的親朋好友。\n- 永久保存您的愛情故事、婚紗照片和珍貴回憶。"},{question:"如何製作電子喜帖？",answer:"只需 3 個簡單步驟，即可製作專屬喜帖：\n\n1. **選擇範本：** 瀏覽我們的範本庫，挑選您喜歡的設計。\n2. **填寫資訊：** 輸入新人姓名、婚禮日期、地點，上傳婚紗照片。\n3. **分享喜帖：** 發佈喜帖後，將專屬連結分享給賓客。"},{question:"費用是多少？",answer:"製作和編輯喜帖完全**免費**！您可以自由設計，不需要任何費用。\n\n發佈後可**免費試用 3 天**，享有所有完整功能。之後只需一次性付款，喜帖即可永久使用。付款前會清楚顯示價格。"},{question:"賓客如何收到喜帖？",answer:"您會獲得一個專屬連結，可以透過以下方式分享：\n\n1. **直接傳送連結：** 透過 LINE、Messenger、簡訊或任何通訊軟體分享。\n2. **使用 QR Code：** 將 QR Code 印在紙本喜帖上，賓客掃描即可瀏覽電子喜帖。"},{question:"需要設計技能嗎？",answer:"完全不需要！所有範本都由專業團隊設計。您只需選擇範本並填寫資訊，不需要調整排版、選字型或配色。"},{question:"需要準備哪些資訊？",answer:"為了快速製作喜帖，請先準備以下資訊：\n\n- **新人資訊：** 新郎、新娘全名\n- **家長資訊：** 雙方父母姓名\n- **婚禮詳情：** 儀式及宴客的日期、時間、地點\n- **婚紗照片：** 5-10 張最喜歡的照片\n- **銀行帳戶：** 如需透過 QR Code 收紅包"},{question:"發佈後還能修改嗎？",answer:"可以！發佈後隨時都能修改喜帖上的所有內容。修改後會立即更新在已分享的連結上，不需要重新傳送。"},{question:"可以邀請多少位賓客？",answer:"沒有人數限制！只要分享喜帖連結，就能邀請所有親朋好友。"}],p=[{question:"\xbfQu\xe9 es una invitaci\xf3n de boda online?",answer:"Una invitaci\xf3n de boda online es una p\xe1gina digital con un dise\xf1o cuidado que sustituye a las invitaciones de papel tradicionales. Con [ChungDoi.com](/es) puedes:\n\n- Crear invitaciones de boda preciosas con funciones como los mensajes de los invitados, los regalos mediante c\xf3digo QR y la gesti\xf3n inteligente de la lista de invitados.\n- Invitar f\xe1cilmente a tus seres queridos est\xe9n donde est\xe9n en el mundo.\n- Guardar para siempre vuestra historia de amor, vuestras fotos y vuestros recuerdos en un recuerdo digital."},{question:"\xbfC\xf3mo se crea una invitaci\xf3n de boda online?",answer:"Puedes crear tu invitaci\xf3n de boda en 3 sencillos pasos:\n\n1. **Elige una plantilla:** Explora nuestra biblioteca y escoge el dise\xf1o que mejor os represente.\n2. **A\xf1ade vuestros datos:** Completa los nombres de la pareja, la fecha, el lugar y sube vuestras fotos.\n3. **Comp\xe1rtela:** Publica tu invitaci\xf3n y comparte el enlace exclusivo con los invitados."},{question:"\xbfCu\xe1nto cuesta?",answer:"Crear y personalizar tu invitaci\xf3n es totalmente **gratis**. Puedes dise\xf1arla como quieras, sin ning\xfan coste.\n\nTras publicarla, disfrutas de un **periodo de prueba gratuito de 3 d\xedas** con todas las funciones. Despu\xe9s, un \xfanico pago mantiene tu invitaci\xf3n activa para siempre. El precio se muestra con claridad antes de cualquier confirmaci\xf3n."},{question:"\xbfC\xf3mo reciben la invitaci\xf3n los invitados?",answer:"Recibes un enlace exclusivo para compartir con los invitados. Puedes:\n\n1. **Enviar el enlace directamente:** Por WhatsApp, Messenger, correo electr\xf3nico o cualquier aplicaci\xf3n de mensajer\xeda.\n2. **Usar un c\xf3digo QR:** Imprime el c\xf3digo QR en invitaciones de papel para que los invitados lo escaneen y abran tu invitaci\xf3n digital al instante."},{question:"\xbfNecesito saber de dise\xf1o?",answer:"Para nada. Todas las plantillas las crean profesionales. Solo tienes que elegir una plantilla y rellenar tus datos, sin necesidad de ajustar la maquetaci\xf3n, escoger tipograf\xedas ni combinar colores."},{question:"\xbfQu\xe9 informaci\xf3n debo preparar?",answer:"Para crear tu invitaci\xf3n en un momento, ten a mano estos datos:\n\n- **Datos de la pareja:** Nombres completos de la novia y el novio\n- **Datos de la familia:** Nombres de los padres\n- **Detalles del evento:** Fecha, hora y lugar de la ceremonia y del banquete\n- **Fotos:** De 5 a 10 de vuestras fotos de boda favoritas\n- **Datos bancarios:** N\xfamero de cuenta, por si quer\xe9is recibir regalos mediante c\xf3digo QR"},{question:"\xbfPuedo editarla despu\xe9s de publicarla?",answer:"S\xed. Puedes editar toda tu invitaci\xf3n en cualquier momento, incluso despu\xe9s de publicarla. Todos los cambios se actualizan al instante en el enlace que ya has compartido, sin necesidad de volver a enviarlo."},{question:"\xbfA cu\xe1ntos invitados puedo invitar?",answer:"El n\xfamero de invitados es ilimitado. Solo tienes que compartir el enlace de tu invitaci\xf3n y repartir la alegr\xeda a todo el mundo."}],g=[{question:"Web招待状とは何ですか。",answer:"Web招待状とは、紙の招待状に代わる、美しくデザインされたデジタルの案内ページです。[ChungDoi.com](/ja) なら、次のことができます。\n\n- ゲストからのメッセージ、QRコードでのご祝儀、かしこい参加者リスト管理などの機能を備えた、素敵な結婚式の招待状を作成できます。\n- 世界のどこにいる大切な方にも、かんたんにご案内をお届けできます。\n- おふたりの物語や写真、思い出を、デジタルの記念として永く残せます。"},{question:"Web招待状はどうやって作りますか。",answer:"かんたんな3ステップで招待状を作成できます。\n\n1. **テンプレートを選ぶ:** ライブラリを見て、おふたりらしいデザインをお選びください。\n2. **情報を入力する:** おふたりのお名前、日付、会場を入力し、写真をアップロードします。\n3. **共有する:** 招待状を公開し、専用リンクをゲストに送るだけです。"},{question:"費用はいくらかかりますか。",answer:"招待状の作成とカスタマイズは、完全に**無料**です。費用をかけずに、思いのままにデザインできます。\n\n公開後は、すべての機能を使える**3日間の無料お試し期間**をお楽しみいただけます。その後は、一度のお支払いで招待状を永久に有効にできます。料金は、ご確定前にはっきりと表示されます。"},{question:"ゲストはどのように招待状を受け取りますか。",answer:"ゲストと共有するための専用リンクをお受け取りいただけます。次の方法でお届けできます。\n\n1. **リンクを直接送る:** LINE、Messenger、メール、各種メッセージアプリでお送りできます。\n2. **QRコードを使う:** 紙の招待状にQRコードを印刷しておけば、ゲストが読み取るだけですぐにデジタル招待状を開けます。"},{question:"デザインの知識は必要ですか。",answer:"まったく必要ありません。すべてのテンプレートはプロが制作しています。テンプレートを選んで情報を入力するだけで、レイアウトの調整やフォント選び、配色を考える必要はありません。"},{question:"どんな情報を準備すればよいですか。",answer:"すぐに招待状を作れるよう、次の情報をご用意ください。\n\n- **おふたりの情報:** 新婦と新郎のフルネーム\n- **ご家族の情報:** ご両親のお名前\n- **イベントの詳細:** 挙式と披露宴の日時・会場\n- **写真:** お気に入りのウェディングフォト5～10枚\n- **口座情報:** QRコードでご祝儀を受け取りたい場合の口座番号"},{question:"公開した後でも編集できますか。",answer:"はい。公開後でも、いつでも招待状全体を編集できます。すべての変更は共有済みのリンクに即座に反映されるので、送り直す必要はありません。"},{question:"何名まで招待できますか。",answer:"招待できる人数に制限はありません。招待状のリンクを共有するだけで、みなさまに喜びをお届けできます。"}]}}]);